entries[202636] = { ["name"] = "Rudelführer", ["text"] = "40 Meter Reichweite\nSofort\nWenn Ihr Euch in Katzengestalt befindet, wird die Bewegungsgeschwindigkeit aller Schlachtzugsmitglieder innerhalb von 20 Metern um 10% erhöht.\n\nZusätzlich heilen sich von 'Rudelführer' betroffene Verbündete selbst um 3% ihrer maximalen Gesundheit, wenn sie mit einem direkten Angriff kritisch treffen. Dieser Heileffekt kann nur einmal alle 8 Sek. auftreten.\n(8s Abklingzeit)" }
